<?php require __DIR__.'/bootstrap.php';$u=require_admin();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if(($_POST['action']??'')==='manga'){$title=trim($_POST['title']??'');$slug=strtolower(trim(preg_replace('~[^a-z0-9]+~','-',iconv('UTF-8','ASCII//TRANSLIT',$title)),'-'));if(!$title)throw new RuntimeException('Informe o título.');$pdo->prepare('INSERT INTO mangas(publisher_id,title,slug,synopsis,rating,status) VALUES(?,?,?,?,?,?)')->execute([$u['publisher_id']?:default_publisher(),$title,$slug,trim($_POST['synopsis']??''),$_POST['rating']??'L',$_POST['status']??'draft']);flash('ok','Mangá cadastrado.');}else{$pdo->prepare('INSERT INTO chapters(manga_id,number,title,content_url,minimum_plan,published_at) VALUES(?,?,?,?,?,NOW())')->execute([(int)$_POST['manga_id'],(int)$_POST['number'],trim($_POST['chapter_title']),trim($_POST['content_url']),$_POST['minimum_plan']]);flash('ok','Capítulo publicado.');}header('Location: admin_catalog.php');exit;}catch(Throwable $e){$err=$e->getMessage();}}$ok=flash('ok');$mangas=$pdo->query('SELECT * FROM mangas ORDER BY id DESC')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catálogo — Administração</title><link rel="stylesheet" href="assets/app.css"></head><body class="adminskin"><aside class="side"><a class="side-logo">ARENA DE <b>AÇO</b><small>ADMINISTRAÇÃO</small></a><a href="admin.php">⌂ Dashboard</a><a class="active" href="admin_catalog.php">▣ Mangás e capítulos</a><a href="video_novo.php">▻ Vídeos Ultimate</a><a href="admin_tickets.php">♧ Suporte</a></aside><main class="adminmain"><header class="adminhead"><div><h1>Catálogo</h1><span>Cadastre mangás e publique capítulos.</span></div></header><?php if($ok):?><p class="alert ok"><?=e($ok)?></p><?php endif?><?php if($err):?><p class="alert err"><?=e($err)?></p><?php endif?><div class="ticket-admin-grid"><section class="panel"><h2>Novo mangá</h2><form method="post"><input type="hidden" name="action" value="manga"><label>Título<input name="title" required></label><label>Sinopse<textarea name="synopsis"></textarea></label><label>Classificação<select name="rating"><option>L</option><option>10</option><option>12</option><option>14</option><option>16</option><option>18</option></select></label><label>Status<select name="status"><option value="draft">Rascunho</option><option value="published">Publicado</option></select></label><button class="redbtn">Salvar mangá</button></form></section><section class="panel"><h2>Novo capítulo</h2><form method="post"><input type="hidden" name="action" value="chapter"><label>Mangá<select name="manga_id" required><?php foreach($mangas as $m):?><option value="<?=$m['id']?>"><?=e($m['title'])?></option><?php endforeach?></select></label><label>Número<input type="number" min="1" name="number" required></label><label>Título<input name="chapter_title" required></label><label>Link/conteúdo<input name="content_url" placeholder="URL do capítulo" required></label><label>Plano mínimo<select name="minimum_plan"><option value="basic">Básico</option><option value="premium">Premium</option><option value="ultimate">Ultimate</option></select></label><button class="redbtn">Publicar capítulo</button></form></section></div><section class="panel"><h2>Mangás cadastrados</h2><?php foreach($mangas as $m):?><div class="row"><span><b><?=e($m['title'])?></b><small> · <?=e($m['rating'])?> · <?=e($m['status'])?></small></span><small><?=e($m['slug'])?></small></div><?php endforeach;if(!$mangas):?><p class="muted">Nenhum mangá cadastrado ainda.</p><?php endif?></section></main></body></html>
